let member=null,signupEnabled=false,memberLoaded=false,fellowshipTab='message',accountTab='login',fellowshipPosts=[],nextFeedCursor=null,voiceRecordingFile=null,voiceRecorder=null,voiceStream=null,voiceGeneration=0;let adminSignedIn=false;let state,version,cart=[],month=new Date(),tab='Brand & homepage';
const $=s=>document.querySelector(s),E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n);
const notice=s=>'<div class="notice">'+s+'</div>';
const link=(href,text)=>'<a class="button" href="'+href+'">'+text+' <span>↗</span></a>';
const banner=(k,h,p)=>'<div class="page-banner"><div class="eyebrow">'+k+'</div><h1 class="page-title">'+h+'</h1><p class="lede">'+p+'</p></div>';
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed.');return d;}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function modal(html){$('#dialogbody').innerHTML=html;$('#dialog').showModal()}
function configure(){document.documentElement.style.setProperty('--blue',state.accent);$('#announcement').textContent=state.announcement;document.title=state.title;$('#year').textContent=new Date().getFullYear();}
const DEMO=[{title:'FTR Signature Tee',category:'Apparel',price:28,concept:true,kind:'tee'},{title:'Finish The Race Hoodie',category:'Apparel',price:52,concept:true,kind:'hoodie'},{title:'FTR Logo Decal',category:'Accessories',price:8,concept:true,kind:'decal'}];
function illustration(p){if(p.image)return '<img loading="lazy" src="'+E(p.image)+'" alt="'+E(p.title)+'">';if(p.kind==='decal')return '<img src="/brand/wordmark-cutout.png" style="object-fit:contain;width:85%" alt="Finish The Race logo decal concept">';return '<svg viewBox="0 0 400 400" role="img" aria-label="'+E(p.title)+' concept illustration"><path d="M125 55 L70 84 L22 173 L88 201 L111 161 L111 347 Q200 366 289 347 L289 161 L312 201 L378 173 L330 84 L275 55 L235 43 Q200 83 165 43Z" fill="'+(p.kind==='hoodie'?'#bfc5cb':'#080b0e')+'" stroke="'+(p.kind==='hoodie'?'#8a939d':'#3d454d')+'" stroke-width="2"/>'+(p.kind==='hoodie'?'<path d="M160 45 Q150 -5 200 5 Q250 -5 240 45 Q200 110 160 45" fill="#a5adb4" stroke="#7b858d"/><path d="M156 292 L244 292 L257 331 L144 331Z" fill="#acb4bb"/>':'')+'<image href="/brand/wordmark-cutout.png" x="127" y="142" width="147" height="80"/></svg>'}
function product(p,i){return '<article class="product"><button data-product="'+i+'" class="product-image" style="border:0;width:100%" aria-label="View '+E(p.title)+'">'+illustration(p)+(p.concept?'<span class="label">Design concept</span>':'')+'</button><div class="product-info"><div><h3>'+E(p.title)+'</h3><p>'+E(p.category||'Merchandise')+'</p></div><span class="price">'+money(p.price)+'</span></div></article>'}
function products(){return state.products.length?state.products:DEMO}
function eventCard(x){const date=new Date(x.date+'T12:00:00');const details='<div class="date-box"><small>'+date.toLocaleString('en-US',{month:'short'}).toUpperCase()+'</small><strong>'+date.getDate()+'</strong><small>'+date.getFullYear()+'</small></div><div class="event-content"><h3>'+E(x.title)+'</h3><p>'+E(x.location||'Location to be announced')+'</p><p>'+E(x.description||'')+'</p></div><button class="filter" data-calendar="'+E(x.id)+'">Add to calendar ↗</button>';return x.image?'<article id="event-'+E(x.id)+'" class="event-card"><button class="event-poster" data-event-poster="'+E(x.id)+'" aria-label="View full flyer for '+E(x.title)+'"><img loading="lazy" src="'+E(x.image)+'" alt="'+E(x.title)+' event flyer"><span>View full flyer ↗</span></button><div class="empty-event">'+details+'</div></article>':'<article id="event-'+E(x.id)+'" class="empty-event">'+details+'</article>';}
function eventsList(){const events=state.events.filter(x=>x.date>=new Date().toLocaleDateString('en-CA')).sort((a,b)=>a.date.localeCompare(b.date));return events.length?events.map(eventCard).join(''): '<div class="empty-event"><div class="date-box"><strong>→</strong><small>UP NEXT</small></div><div class="event-content"><h3>The next chapter starts here.</h3><p>Upcoming meets and event details will appear here when announced.</p><span class="pill">Calendar coming soon</span></div><a class="textlink" href="#newsletter">Stay in the loop ↗</a></div>'}
function photos(limit=99){return state.gallery.length?state.gallery.slice(0,limit).map((x,i)=>'<button class="photo" data-photo="'+i+'" aria-label="View '+E(x.title)+'"><img loading="lazy" src="'+E(x.image)+'" alt="'+E(x.title)+'"><small>'+E(x.title)+'</small></button>').join(''):['The cars','The people','The purpose'].map((t,i)=>'<div class="photo"><span class="index">0'+(i+1)+'</span><span class="placeholder">'+t+'</span><small>Event photos coming soon</small></div>').join('')}
function newsletter(){return '<section class="newsletter" id="newsletter"><div><h2>Don’t miss<br>the next meet.</h2><p>Event announcements, encouragement, and updates from the FTR community.</p></div><form id="newsletterform"><input type="email" name="email" aria-label="Email address" placeholder="Your email address" required maxlength="254"><button type="submit">JOIN THE LIST ↗</button><label class="consent"><input type="checkbox" name="consent" required><span>I agree to receive email updates. This preview saves signups; email delivery is not connected yet. <a href="#/privacy">Privacy policy</a>.</span></label></form></section>'}
function homepage(){const words=state.tagline.split('.').map(s=>s.trim()).filter(Boolean),motion=matchMedia('(prefers-reduced-motion: reduce)').matches;return '<section class="community-hero"><div class="community-hero-copy"><img class="home-logo" src="/brand/mark-cutout.png" alt="FTR Motorsports"><div class="eyebrow">Finish The Race Motorsports</div><h1>'+words.map((s,i)=>i===1?'<span>'+E(s)+'.</span>':E(s)+'.').join('<br>')+'</h1><p>'+E(state.intro)+'</p><div class="actions">'+link('#/events','Find your next meet')+'<a class="button outline" href="#/fellowship">Join the fellowship ↗</a></div><small>KEEP THE FAITH. FINISH THE RACE.</small></div><div class="community-video"><div class="video-label"><span>Life in the FTR community</span><span>2 Timothy 4:7</span></div>'+(state.video?'<video id="home-video" '+(!motion?'autoplay':'')+' muted loop controls playsinline preload="metadata" aria-label="Finish The Race compilation video" src="'+E(state.video)+'"></video><p>Turn on sound, pause, or go fullscreen using the player controls.</p>':'<div class="video-empty"><span class="play-symbol">▶</span><h2>Cars bring us together.<br>Faith keeps us moving.</h2><p>The FTR compilation video will appear here.</p></div>')+'</div></section><div class="stripe">CARS <i>✦</i> COMMUNITY <i>✦</i> CHRIST <i>✦</i> CARS <i>✦</i> COMMUNITY <i>✦</i> CHRIST</div><section class="section"><div class="section-head"><div><div class="eyebrow">Pull up. Connect.</div><h2>See you at the next one.</h2></div><a class="textlink" href="#/events">View the calendar ↗</a></div>'+eventsList()+'</section><section class="section dark"><div class="section-head"><div><div class="eyebrow">Encouragement for the journey</div><h2>Messages from FTR.</h2><p>A place for encouragement, testimonies, and prayer.</p></div><a class="textlink" href="#/fellowship">Visit Fellowship ↗</a></div><div id="home-fellowship" class="home-message-grid"><div class="empty">Loading the latest messages…</div></div><div class="fellowship-invites"><a href="#/fellowship?tab=testimony"><strong>Share your testimony ↗</strong><span>Tell the community how faith has met you along the way.</span></a><a href="#/fellowship?tab=prayer"><strong>Ask for prayer ↗</strong><span>You don’t have to be a member to reach out.</span></a></div></section><section class="section mission"><div class="mission-art"><p class="verse">Keep the faith.<br><span>Finish the race.</span></p><small>2 TIMOTHY 4:7 · OUR FOUNDATION</small></div><div><div class="eyebrow">More than a car meet</div><h2>A shared passion.<br>A greater purpose.</h2><p class="lede">'+E(state.about)+'</p><a class="textlink" href="#/about">Discover our mission ↗</a></div></section><section class="section dark"><div class="section-head"><div><div class="eyebrow">Life in the FTR community</div><h2>The moments that move us.</h2></div><a class="textlink" href="#/gallery">Explore the gallery ↗</a></div><div class="gallery-grid">'+photos(3)+'</div></section>'+newsletter()}
function about(){return banner('Our mission','More than motorsports.','A love of cars. A life of faith. A community with purpose.')+'<section class="section mission"><div><div class="eyebrow">Finish The Race</div><h2>Driven by<br>something greater.</h2><p class="lede">'+E(state.about)+'</p><div class="actions">'+link('#/events','Join us at a meet')+'</div></div><div class="mission-art"><img src="/brand/wordmark-cutout.png" alt="Finish The Race Motorsports"><small style="margin-top:30px">2 TIMOTHY 4:7</small></div></section>'+newsletter()}
function calendar(){const y=month.getFullYear(),m=month.getMonth(),start=new Date(y,m,1).getDay(),count=new Date(y,m+1,0).getDate();let cells='';for(let i=0;i<Math.ceil((start+count)/7)*7;i++){const n=i-start+1,key=y+'-'+String(m+1).padStart(2,'0')+'-'+String(n).padStart(2,'0');cells+='<div class="day '+(new Date().toDateString()===new Date(y,m,n).toDateString()?'today':'')+'">'+(n>0&&n<=count?n+state.events.filter(x=>x.date===key).map(x=>'<a href="#event-'+E(x.id)+'">'+E(x.title)+'</a>').join(''):'')+'</div>'}return '<div class="calendar"><div class="calhead"><button id="prevmonth" aria-label="Previous month">←</button><h3>'+month.toLocaleString('en-US',{month:'long',year:'numeric'})+'</h3><button id="nextmonth" aria-label="Next month">→</button></div><div class="calgrid">'+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>'<div class="dayname">'+x+'</div>').join('')+cells+'</div></div>'}
function events(){return banner('Come as you are','Your next meet starts here.','Explore upcoming events and connect with the FTR community.')+'<section class="section">'+calendar()+'<h2 style="font-size:30px;margin-bottom:30px">Upcoming events</h2>'+eventsList()+'</section>'+newsletter()}
function shop(){return banner('The FTR collection','Wear what drives you.','Merchandise with a purpose.')+'<section class="section">'+(!state.products.length?notice('These are illustrative product concepts and example prices. Checkout is disabled until actual merchandise, inventory, shipping, and payments are configured.'):'')+'<div class="filters"><button class="filter active" data-filter="All">All</button><button class="filter" data-filter="Apparel">Apparel</button><button class="filter" data-filter="Accessories">Accessories</button></div><div class="grid3" id="products">'+products().map(product).join('')+'</div></section>'+newsletter()}
function gallery(){return banner('The gallery','Every meet. Every moment.','Cars, community, and the memories made along the way.')+'<section class="section"><div class="gallery-grid">'+photos()+'</div></section>'+newsletter()}
function contact(){return banner('Get in touch','Let’s connect.','Questions about an event, merchandise, or the mission? Start here.')+'<section class="section form-grid"><div><h2>We’d love to<br>hear from you.</h2><p class="lede">Send a message to the Finish The Race team.</p>'+(state.email?'<a class="textlink" href="mailto:'+E(state.email)+'">'+E(state.email)+'</a>':'<p class="lede">Public contact email will be added before launch.</p>')+'</div><form id="contactform" class="form"><label>Your name<input name="name" required maxlength="200" autocomplete="name"></label><label>Email address<input name="email" required type="email" autocomplete="email"></label><label>Your message<textarea name="message" required minlength="5" maxlength="5000"></textarea></label><label class="hidden-field" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><p class="lede" style="font-size:11px">In this website preview, messages are saved to the admin inbox. Email notifications are not connected.</p><button class="button">Send message ↗</button></form></section>'}
function privacy(){return banner('Privacy','Your information matters.','Draft for this website preview. Update for the final business and connected services before public launch.')+'<section class="section prose"><h3>Who operates this website</h3><p>Finish The Race Motorsports. The legal business name and privacy contact must be supplied before launch.</p><h3>Information this preview collects</h3><p>If you submit a member picture, it is stored privately until its associated public post is approved. If you submit a contact form or prayer request, we store the fields you provide and the submission time. Community submissions are screened for blocked language and screened before publication. If you subscribe, we store your email address, consent, and signup time. Admin access uses a password and a necessary session cookie. Public visitors can browse without an account. Free member registration stores your full name, email, public display name, address, and a salted password hash. Your full name, email, and address are never included in public fellowship posts. This version does not process payments.</p><h3>How information is used</h3><p>Information is used to manage member accounts, verify email, recover passwords, review inquiries, prepare a newsletter list, and moderate testimonies and prayer requests. Private prayer requests are visible only to the FTR admin; requests chosen for public sharing appear only after review. Newsletter delivery is not enabled. We do not sell information collected by this preview.</p><h3>Storage and services</h3><p>Content and submissions are stored using Cloudflare R2 and D1. Verification and password-recovery emails are sent through Resend when configured. Recording an admin voice message requests microphone permission and saves the audio only when the admin submits it. The necessary admin session cookie expires after eight hours; the member session cookie expires after seven days. Public visitors do not need either cookie to read published content or submit a prayer request. When live checkout and email services are connected, this policy must be updated to describe those services, cookies, retention, and choices.</p><h3>Your choices</h3><p>Contact the operator to request access, correction, deletion, or removal from the newsletter list. A working public contact address and newsletter unsubscribe mechanism must be in place before launch.</p><h3>Retention and updates</h3><p>The operator must establish a retention schedule before public launch. This draft describes the current preview only.</p></section>'}
const tabs=['Brand & homepage','Events','Messages from FTR','Community moderation','Members','Gallery','Products','Messages','Newsletter','Launch checklist'];
function label(name,title,type='text'){return '<label>'+title+'<input name="'+name+'" type="'+type+'" value="'+E(state[name])+'"></label>'}
function admin(){if(!adminSignedIn)return banner('Website management','Admin sign-in.','Sign in to manage Finish The Race Motorsports.')+'<section class="section"><form id="adminlogin" class="form" style="max-width:440px"><label>Admin password<input name="password" type="password" required autocomplete="current-password"></label><button class="button">Sign in →</button></form></section>';return banner('Website management','Your brand. Your controls.','Manage website content. Changes are saved across devices.')+'<section class="section admin-grid"><div class="adminnav"><button id="adminlogout">Sign out ↗</button>'+tabs.map(x=>'<button data-tab="'+x+'" class="'+(tab===x?'active':'')+'">'+x+'</button>').join('')+'</div><div class="admin-panel" id="adminpanel"></div></section>'}
function adminPanel(){const panel=$('#adminpanel');if(!panel)return;let html='';if(tab==='Brand & homepage'){html='<form id="brandform" class="form"><div class="row">'+label('title','Website title')+label('accent','Accent color','color')+'</div>'+label('announcement','Top announcement')+label('tagline','Hero headline (separate lines with periods)')+label('intro','Hero introduction')+'<label>About / mission<textarea name="about">'+E(state.about)+'</textarea></label><div class="row">'+label('email','Public contact email','email')+label('instagram','Instagram link','url')+'</div>'+label('video','Compilation video URL (direct MP4 or WebM)')+'<label>Or upload a video (up to 35 MB)<input type="file" id="videofile" accept="video/mp4,video/webm"></label><button class="button">Save website ↗</button></form>';}
else if(['Events','Products','Gallery'].includes(tab)){const kind=tab.toLowerCase();html='<div class="section-head"><h2 style="font-size:28px">'+tab+'</h2><button class="button" id="additem" data-kind="'+kind+'">Add '+(tab==='Gallery'?'photo':kind.slice(0,-1))+' +</button></div>'+(!state[kind].length?'<div class="empty">No '+kind+' yet. Add your first one.</div>':state[kind].map((x,i)=>'<div class="itemrow"><div><h3>'+E(x.title)+'</h3><p>'+E(x.date||x.category||'')+'</p></div><div><button data-edit="'+i+'" data-kind="'+kind+'">Edit</button> <button data-delete="'+i+'" data-kind="'+kind+'">Remove</button></div></div>').join(''));}
else if(tab==='Launch checklist'){html=notice('This is the design and content-management foundation. It is not yet a live commerce website.')+'<div class="prose"><h3>Brand and content</h3><p>Upload the compilation video, actual merchandise photos, sizes, prices, stock quantities, event dates, and the final About Us story.</p><h3>Members and Fellowship</h3><p>Connect D1, apply the migration, and configure verification/recovery email. Free accounts, profiles, testimonies, guest prayer requests, and moderation are implemented. Test signup, verification, login, and approval on your deployed site.</p><h3>Payments and orders</h3><p>Connect the owner’s Stripe business account. Add server-priced checkout, payment webhook verification, inventory reservation, shipping, tax handling, refunds, tracking, and order history.</p><h3>Email and policies</h3><p>Connect a verified sending domain, newsletter delivery with unsubscribe, contact alerts, and order receipts. Finalize privacy, terms, shipping, and returns policies.</p><h3>Public hosting</h3><p>Hosting is configured for your own Cloudflare account. Admin access uses a separate password and signed session cookie. Free member accounts are implemented and require database/email setup. Live commerce remains a separate future phase.</p></div>';}
else if(['Messages from FTR','Community moderation','Members'].includes(tab)){html='<div class="empty">Loading…</div>';loadCommunityAdmin(tab).catch(e=>{if($('#adminpanel'))$('#adminpanel').innerHTML=notice(E(e.message));});}else{html='<div class="empty">Loading…</div>';loadRecords(tab).catch(e=>toast(e.message));}panel.innerHTML=html;}
async function loadRecords(t){const d=await api('/api/admin/records?type='+(t==='Newsletter'?'newsletter':'messages'));if(tab!==t)return;$('#adminpanel').innerHTML='<h2 style="font-size:28px">'+t+'</h2>'+(!d.records.length?'<div class="empty">No '+t.toLowerCase()+' yet.</div>':d.records.map(x=>'<div class="itemrow"><div><h3>'+E(x.name||x.email)+'</h3><p>'+E(x.email)+' · '+E(new Date(x.created).toLocaleString())+'</p><p style="margin-top:15px">'+E(x.message||'Consent recorded · Email delivery disabled')+'</p></div></div>').join(''));}
async function save(){const d=await api('/api/content','PUT',{data:state,version});state=d.data;version=d.version;configure();toast('Changes saved.');}
async function upload(file){if(!file)return '';if(file.size>35*1024*1024)throw Error('Use a file smaller than 35 MB.');const r=await fetch('/api/upload',{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);return d.url;}
function itemEditor(kind,i){const x=i===undefined?{}:state[kind][i];modal('<h2 class="modal-title">'+(i===undefined?'Add':'Edit')+' '+(kind==='gallery'?'photo':kind.slice(0,-1))+'</h2><form id="itemform" class="form" data-kind="'+kind+'" data-index="'+(i??'')+'"><label>Title<input name="title" required maxlength="200" value="'+E(x.title)+'"></label>'+(kind==='events'?'<div class="row"><label>Date<input type="date" name="date" required value="'+E(x.date)+'"></label><label>Location<input name="location" value="'+E(x.location)+'"></label></div><label>Description<textarea name="description">'+E(x.description)+'</textarea></label>':'')+(kind==='products'?'<div class="row"><label>Example price ($)<input name="price" type="number" min="0" step="0.01" required value="'+E(x.price??0)+'"></label><label>Category<select name="category"><option '+(x.category==='Apparel'?'selected':'')+'>Apparel</option><option '+(x.category==='Accessories'?'selected':'')+'>Accessories</option></select></label></div><label>Description<textarea name="description">'+E(x.description)+'</textarea></label>':'')+(x.image?'<img class="event-image-preview" src="'+E(x.image)+'" alt="Current image for '+E(x.title)+'">':'')+'<label>Image URL<input name="image" value="'+E(x.image)+'" placeholder="https://… or an uploaded image"></label><label>Or upload photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><button class="button">Save '+(kind==='gallery'?'photo':'item')+'</button></form>');}
function fitHomeVideo(){const video=$('#home-video');if(!video)return;const fit=()=>{if(video.videoWidth>0&&video.videoHeight>0)video.style.setProperty('--video-ratio',String(video.videoWidth/video.videoHeight));};video.addEventListener('loadedmetadata',fit);video.addEventListener('resize',fit);fit();}
function render(){$('#account').textContent=member?'My profile ↗':'Join / sign in ↗';const route=(location.hash||'#/').split('?')[0].slice(2);const params=new URLSearchParams(location.hash.split('?')[1]||'');if(route==='fellowship'&&['message','testimony','prayer'].includes(params.get('tab')))fellowshipTab=params.get('tab');const pages={'':homepage,about,events,shop,gallery,contact,privacy,admin,fellowship,account};$('#main').innerHTML=(pages[route]||homepage)();document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.getAttribute('href')===(location.hash||'#/')));$('#nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(route==='admin'&&adminSignedIn)adminPanel();if(route==='fellowship')loadFellowship();if(route===''){fitHomeVideo();loadHomeMessages();}if(route==='account'){loadAccount(params);}}
function productModal(i){const p=products()[i];modal('<div class="product-image">'+illustration(p)+'</div><h2 class="modal-title">'+E(p.title)+'</h2><p class="modal-copy">'+E(p.description||'Represent the Finish The Race mission.')+'</p><p>'+money(p.price)+'</p>'+notice(p.concept?'This is an illustrative merchandise concept with an example price.':'Merchandise preview. Inventory and live checkout are not configured.')+'<button class="button" id="addcart" data-index="'+i+'">Add to preview bag +</button>');}
function cartModal(){modal('<h2 class="modal-title">Your preview bag</h2>'+(!cart.length?'<p class="modal-copy">Your bag is empty.</p>':cart.map((p,i)=>'<div class="cartrow"><span>'+E(p.title)+' × '+p.qty+'</span><span>'+money(p.price*p.qty)+'</span><button data-remove="'+i+'" aria-label="Remove '+E(p.title)+'">×</button></div>').join('')+'<div class="carttotal"><strong>Subtotal</strong><strong>'+money(cart.reduce((n,p)=>n+p.price*p.qty,0))+'</strong></div>')+notice('Checkout is not connected. This preview bag does not reserve stock or create an order.')+'<button class="button" disabled>Checkout — setup required</button>');}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.id==='adminlogout'){await api('/api/auth/logout','POST',{});adminSignedIn=false;render();}else if(b.matches('.close'))$('#dialog').close();else if(b.id==='menu'){const open=$('#nav').classList.toggle('open');b.setAttribute('aria-expanded',String(open))}else if(b.id==='account')location.hash='#/account';else if(b.id==='cart')cartModal();else if(b.hasAttribute('data-product'))productModal(Number(b.dataset.product));else if(b.id==='addcart'){const p=products()[Number(b.dataset.index)],found=cart.find(x=>x.title===p.title);if(found)found.qty++;else cart.push({...p,qty:1});$('#bagcount').textContent=cart.reduce((n,p)=>n+p.qty,0);$('#dialog').close();toast('Added to preview bag.')}else if(b.hasAttribute('data-remove')){cart.splice(Number(b.dataset.remove),1);$('#bagcount').textContent=cart.reduce((n,p)=>n+p.qty,0);cartModal();}else if(b.hasAttribute('data-filter')){document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));$('#products').innerHTML=products().map((p,i)=>b.dataset.filter==='All'||p.category===b.dataset.filter?product(p,i):'').join('');}else if(b.hasAttribute('data-tab')){tab=b.dataset.tab;render();}else if(b.id==='additem')itemEditor(b.dataset.kind);else if(b.hasAttribute('data-edit'))itemEditor(b.dataset.kind,Number(b.dataset.edit));else if(b.hasAttribute('data-delete')){modal('<h2 class="modal-title">Remove this item?</h2><p class="modal-copy">'+E(state[b.dataset.kind][Number(b.dataset.delete)].title)+'</p><button class="button" id="confirmdelete" data-kind="'+b.dataset.kind+'" data-index="'+b.dataset.delete+'">Remove item</button>');}else if(b.id==='confirmdelete'){state[b.dataset.kind].splice(Number(b.dataset.index),1);await save();$('#dialog').close();render();}else if(b.id==='prevmonth'||b.id==='nextmonth'){month.setMonth(month.getMonth()+(b.id==='prevmonth'?-1:1),1);render();}else if(b.hasAttribute('data-event-poster')){const x=state.events.find(x=>x.id===b.dataset.eventPoster);if(x?.image)modal('<img class="full-event-poster" src="'+E(x.image)+'" alt="'+E(x.title)+' event flyer"><h2 class="modal-title">'+E(x.title)+'</h2>');}else if(b.hasAttribute('data-photo')){const p=state.gallery[Number(b.dataset.photo)];modal('<img src="'+E(p.image)+'" alt="'+E(p.title)+'"><h2 class="modal-title">'+E(p.title)+'</h2>');}else if(b.id==='video-toggle'){const v=$('video');if(v.paused){await v.play();b.textContent='Pause video'}else{v.pause();b.textContent='Play video'}}else if(b.hasAttribute('data-calendar')){const x=state.events.find(x=>x.id===b.dataset.calendar);const esc=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,c=>'\\'+c);const start=x.date.replaceAll('-','');const next=new Date(x.date+'T12:00:00');next.setDate(next.getDate()+1);const end=next.getFullYear()+String(next.getMonth()+1).padStart(2,'0')+String(next.getDate()).padStart(2,'0');const body=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Finish The Race//Events//EN','BEGIN:VEVENT','UID:'+x.id+'@finishtherace','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z','DTSTART;VALUE=DATE:'+start,'DTEND;VALUE=DATE:'+end,'SUMMARY:'+esc(x.title),'LOCATION:'+esc(x.location),'DESCRIPTION:'+esc(x.description),'END:VEVENT','END:VCALENDAR'].join('\r\n');const url=URL.createObjectURL(new Blob([body],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download='ftr-event.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}catch(err){toast(err.message)}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button[type=submit],button:not([type])');if(b)b.disabled=true;try{const d=Object.fromEntries(new FormData(f));if(f.id==='adminlogin'){await api('/api/auth/login','POST',{password:d.password});adminSignedIn=true;render();toast('Signed in.');}else if(f.id==='newsletterform'){await api('/api/newsletter','POST',{email:d.email,consent:d.consent==='on'});f.reset();toast('Signup saved. Email delivery is not connected yet.');}else if(f.id==='contactform'){await api('/api/contact','POST',d);f.reset();toast('Message saved in the admin inbox.');}else if(f.id==='brandform'){const file=$('#videofile').files[0];if(file)d.video=await upload(file);state={...state,...d};await save();render();}else if(f.id==='itemform'){const kind=f.dataset.kind,idx=f.dataset.index;if(d.photo?.size)d.image=await upload(d.photo);delete d.photo;if(kind==='gallery'&&!d.image)throw Error('Add a photo first.');if(kind==='products')d.price=Number(d.price);d.id=idx===''?crypto.randomUUID():state[kind][Number(idx)].id;if(idx==='')state[kind].push(d);else state[kind][Number(idx)]=d;await save();$('#dialog').close();render();}}catch(err){toast(err.message)}finally{if(b)b.disabled=false}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))$('#dialog').close()});window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/')){render();window.scrollTo(0,0)}});
(async()=>{try{await refreshMember();const auth=await api('/api/auth/session');adminSignedIn=auth.admin;const d=await api('/api/content');state=d.data;version=d.version;configure();render();if(matchMedia('(prefers-reduced-motion: reduce)').matches)$('video')?.pause()}catch(err){$('#main').innerHTML='<section class="section"><h1>We couldn’t load the preview.</h1><p>Please refresh to try again.</p></section>';toast(err.message)}})();
async function refreshMember(){try{const d=await api('/api/members/session');member=d.member;signupEnabled=d.signupEnabled;memberLoaded=true;}catch{member=null;signupEnabled=false;memberLoaded=false;}}
function mediaMarkup(p){let out='';if(p.image&&p.type!=='prayer')out+='<button class="post-image" data-postimage="'+E(p.image)+'" data-title="'+E(p.title)+'"><img loading="lazy" src="'+E(p.image)+'" alt="'+E(p.title)+'"></button>';if(p.type==='message'&&p.video){let yt='',vimeo='';try{const u=new URL(p.video);if(['www.youtube.com','youtube.com'].includes(u.hostname))yt=u.pathname.startsWith('/shorts/')?u.pathname.split('/')[2]:u.searchParams.get('v');if(u.hostname==='youtu.be')yt=u.pathname.slice(1);if(['vimeo.com','www.vimeo.com','player.vimeo.com'].includes(u.hostname)){const candidate=u.pathname.split('/').filter(Boolean).at(-1);if(/^\d+$/.test(candidate))vimeo=candidate;}}catch{}if(yt&&/^[a-zA-Z0-9_-]{11}$/.test(yt))out+='<iframe class="post-video" src="https://www.youtube-nocookie.com/embed/'+yt+'" title="'+E(p.title)+' video" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen></iframe>';else if(vimeo)out+='<iframe class="post-video" src="https://player.vimeo.com/video/'+vimeo+'" title="'+E(p.title)+' video" loading="lazy" allow="fullscreen; picture-in-picture" allowfullscreen></iframe>';else out+='<video class="post-video" controls playsinline preload="metadata" src="'+E(p.video)+'"></video>';}if(p.type==='message'&&p.audio)out+='<div class="post-audio"><span>Voice message</span><audio controls preload="metadata" src="'+E(p.audio)+'"></audio></div>';if(p.type==='message'&&p.link)out+='<a class="textlink" target="_blank" rel="noopener noreferrer" href="'+E(p.link)+'">Open shared link ↗</a>';return out;}
function postCard(p){return '<article class="fellowship-post"><div class="post-meta"><span>'+E(p.type==='message'?'Messages from FTR':p.type==='testimony'?'Member testimony':'Prayer request')+'</span><time datetime="'+E(p.created)+'">'+new Date(p.created).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})+'</time></div><h2>'+E(p.title)+'</h2><p class="post-author">'+E(p.author)+'</p>'+(p.body?'<p class="post-body">'+E(p.body)+'</p>':'')+mediaMarkup(p)+'</article>';}
async function loadHomeMessages(){try{const d=await api('/api/fellowship/feed?type=message');if(!$('#home-fellowship'))return;$('#home-fellowship').innerHTML=d.posts.length?d.posts.slice(0,3).map(postCard).join(''):'<div class="empty">Messages from the FTR team will appear here. In the meantime, explore Fellowship to share a testimony or request prayer.</div>';}catch{if($('#home-fellowship'))$('#home-fellowship').innerHTML='<div class="empty">Visit Fellowship for encouragement, testimonies, and prayer.</div>';}}
function fellowship(){return banner('Faith. Community. Connection.','Fellowship.','A space to encourage one another, share what God is doing, and pray together.')+'<section class="section"><div class="fellowship-tabs"><button data-fellowship="message" class="filter '+(fellowshipTab==='message'?'active':'')+'">Messages from FTR</button><button data-fellowship="testimony" class="filter '+(fellowshipTab==='testimony'?'active':'')+'">Testimonies</button><button data-fellowship="prayer" class="filter '+(fellowshipTab==='prayer'?'active':'')+'">Prayer requests</button></div><div class="fellowship-intro"><div><h2 style="font-size:32px">'+(fellowshipTab==='message'?'A word for the road.':fellowshipTab==='testimony'?'Your story can encourage someone.':'You don’t have to carry it alone.')+'</h2><p class="lede">'+(fellowshipTab==='message'?'The full archive of admin messages: videos, voice memos, pictures, Scripture, and updates from the FTR team.':fellowshipTab==='testimony'?'Members can share pictures, meaningful Scripture, or moments of faith through text. Text-only posts publish after passing the language screen. Posts with pictures require admin review.':'Anyone can request prayer. Keep your request private to FTR or choose to share it on the prayer wall after language screening.')+'</p></div>'+(fellowshipTab==='message'?'':fellowshipTab==='testimony'?'<button class="button" id="write-testimony">Share a testimony +</button>':'<button class="button" id="write-prayer">Request prayer +</button>')+'</div><div id="fellowship-feed" class="fellowship-feed"><div class="empty">Loading…</div></div><button id="more-fellowship" class="button outline" hidden>Load more</button></section>';}
async function loadFellowship(append=false){const requestedTab=fellowshipTab;try{const d=await api('/api/fellowship/feed?type='+fellowshipTab+(append&&nextFeedCursor?'&cursor='+encodeURIComponent(nextFeedCursor):''));if(!$('#fellowship-feed')||requestedTab!==fellowshipTab)return;fellowshipPosts=append?[...fellowshipPosts,...d.posts]:d.posts;nextFeedCursor=d.nextCursor;$('#fellowship-feed').innerHTML=fellowshipPosts.length?fellowshipPosts.map(postCard).join(''):'<div class="empty">'+(fellowshipTab==='message'?'Messages from FTR will appear here.':fellowshipTab==='testimony'?'No published testimonies yet. Your story could be the first.':'No public prayer requests yet. You can still send a private request to FTR.')+'</div>';$('#more-fellowship').hidden=!nextFeedCursor;}catch(e){if($('#fellowship-feed'))$('#fellowship-feed').innerHTML=notice(E(e.message));}}
function communityForm(type){if(type==='testimony'&&!member){location.hash='#/account';toast('Sign in as a member to share a testimony.');return;}modal('<h2 class="modal-title">'+(type==='testimony'?'Share your testimony':'Request prayer')+'</h2><p class="modal-copy">'+(type==='testimony'?'Share encouragement or a Scripture that spoke to you.':'You do not need an account. Requests are private unless you choose to share.')+(type==='testimony'?' Pictures and text only. No voice memos, videos, or links.':' Text only.')+(type==='testimony'?' Text publishes after language screening; posts with pictures wait for admin approval.':' Requests chosen for public sharing publish after language screening; private requests go only to FTR.')+'</p><form id="communityform" class="form" data-type="'+type+'"><label>Title<input name="title" required maxlength="160"></label><label>'+(type==='testimony'?'Your testimony or Scripture':'What would you like prayer for?')+'<textarea name="body" '+(type==='prayer'?'required minlength="10"':'')+' maxlength="5000"></textarea></label>'+ (type==='testimony'?'<label>Picture (optional, JPG/PNG/WebP up to 10 MB)<input type="file" name="memberimage" accept="image/jpeg,image/png,image/webp"></label>':'')+(type==='prayer'?'<label>Your name (optional)<input name="author" maxlength="80" value="'+E(member?.display_name||'')+'"></label><label>Email for FTR to contact you (optional, never shown publicly)<input type="email" name="email" value="'+E(member?.email||'')+'"></label>':'')+'<label class="checklabel"><input type="checkbox" name="anonymous" '+(type==='prayer'?'checked':'')+'> Show my name as Anonymous</label>'+(type==='prayer'?'<label class="checklabel"><input type="checkbox" name="share_public"> Share this on the public prayer wall after language screening</label>':'')+'<label class="checklabel"><input type="checkbox" name="consent_public" '+(type==='testimony'?'required':'')+'> I give permission to publish my submission if I have chosen public sharing.</label><p class="modal-copy">Your account address and email are never included in public posts. Avoid sharing another person’s identifying information without permission.</p><label class="hidden-field" aria-hidden="true">Website<input name="website" tabindex="-1"></label><button class="button">Submit to FTR ↗</button></form>');}
function profileInputs(m={}){return '<div class="row"><label>Full name<input name="name" required autocomplete="name" value="'+E(m.name)+'"></label><label>Public display name<input name="display_name" autocomplete="nickname" value="'+E(m.display_name)+'" placeholder="First name or nickname"></label></div><label>Address line 1<input name="address1" required autocomplete="address-line1" value="'+E(m.address1)+'"></label><label>Address line 2 (optional)<input name="address2" autocomplete="address-line2" value="'+E(m.address2)+'"></label><div class="row"><label>City<input name="city" required autocomplete="address-level2" value="'+E(m.city)+'"></label><label>State / region<input name="region" required autocomplete="address-level1" value="'+E(m.region)+'"></label></div><div class="row"><label>ZIP / postal code<input name="postal" required autocomplete="postal-code" value="'+E(m.postal)+'"></label><label>Country code<input name="country" required value="'+E(m.country||'US')+'" maxlength="2"></label></div>';}
function account(){return banner('FTR membership','Your place in the community.','Free membership for fellowship, testimonies, and your personal profile.')+'<section class="section"><div id="account-content">'+accountContent()+'</div></section>';}
function accountContent(){if(member)return '<div class="form-grid"><div><div class="eyebrow">Welcome, '+E(member.display_name)+'</div><h2>Keep growing.<br>Keep going.</h2><p class="lede">Your email is verified. Your full name and address stay private; only your display name or Anonymous appears with approved posts.</p><div class="actions">'+link('#/fellowship','Visit Fellowship')+'<button class="button outline" id="memberlogout">Sign out</button></div><h3 style="margin-top:40px">Your submissions</h3><div id="myposts"><div class="empty">Loading…</div></div></div><form id="profileform" class="form"><h3>Edit your profile</h3>'+profileInputs(member)+'<button class="button">Save profile</button></form></div>';if(!memberLoaded)return notice('Membership needs the Fellowship database setup. Public pages remain available. Follow FELLOWSHIP-SETUP.md to connect it.');const signup=accountTab==='signup',forgot=accountTab==='forgot',resend=accountTab==='resend';return '<div class="account-wrap"><div class="filters"><button class="filter '+(!signup&&!forgot&&!resend?'active':'')+'" data-accounttab="login">Sign in</button><button class="filter '+(signup?'active':'')+'" data-accounttab="signup">Join FTR</button></div>'+(!signupEnabled?notice('Membership verification and recovery email are not connected yet. Existing verified members can sign in. New registration will be available once FTR connects email delivery.'):'')+'<form class="form" id="'+(signup?'signupform':forgot?'forgotform':resend?'resendform':'memberlogin')+'"><h3>'+(signup?'Create your free member account':forgot?'Reset your password':resend?'Resend your verification link':'Member sign-in')+'</h3><label>Email<input type="email" name="email" required autocomplete="email"></label>'+(!forgot&&!resend?'<label>Password<input name="password" type="password" required '+(signup?'minlength="12" autocomplete="new-password"':'autocomplete="current-password"')+'></label>':'')+(signup?profileInputs()+'<label class="checklabel"><input type="checkbox" name="consent" required> I agree to the <a href="#/privacy">privacy policy</a> and understand that my profile information is private.</label>':'')+'<button class="button" '+((signup||forgot||resend)&&!signupEnabled?'disabled':'')+'>'+(signup?'Create account':forgot||resend?'Send email':'Sign in')+'</button></form><div class="account-tools"><button class="filter" data-accounttab="forgot">Forgot password?</button><button class="filter" data-accounttab="resend">Resend verification</button></div></div>';}
async function loadAccount(params){if(params.has('verify')){$('#account-content').innerHTML='<div class="empty">Verify your email to activate your account.</div><button class="button" id="verifyemail" data-token="'+E(params.get('verify'))+'">Verify my email</button>';return;}if(params.has('reset')){$('#account-content').innerHTML='<div class="account-wrap"><form id="resetform" class="form" data-token="'+E(params.get('reset'))+'"><h3>Choose a new password</h3><label>New password<input type="password" name="password" required minlength="12" autocomplete="new-password"></label><button class="button">Reset password</button></form></div>';return;}if(member){try{const d=await api('/api/members/posts');if($('#myposts'))$('#myposts').innerHTML=d.posts.length?d.posts.map(p=>'<div class="itemrow"><div><h3>'+E(p.title)+'</h3><p>'+E(p.type)+' · '+E(p.visibility)+' · '+E(p.status)+(p.moderation_note?' — '+E(p.moderation_note):'')+'</p></div></div>').join(''):'<p class="lede">No submissions yet.</p>';}catch(e){toast(e.message)}}}
let adminPosts=[],moderationStatus='pending';
async function loadCommunityAdmin(t){const el=$('#adminpanel');if(!el)return;if(t==='Members'){const d=await api('/api/fellowship/admin/members');if(tab!==t||!$('#adminpanel'))return;el.innerHTML='<h2 style="font-size:28px">Members</h2>'+(!d.members.length?'<div class="empty">No members yet.</div>':d.members.map(m=>'<div class="itemrow"><div><h3>'+E(m.name)+'</h3><p>'+E(m.email)+' · '+(m.verified?'Verified':'Awaiting email verification')+'</p></div></div>').join(''));return;}const d=await api('/api/fellowship/admin/posts?type='+(t==='Messages from FTR'?'message':'community')+'&status='+moderationStatus);if(tab!==t||!$('#adminpanel'))return;adminPosts=d.posts;el.innerHTML='<div class="section-head"><h2 style="font-size:28px">'+E(t)+'</h2>'+(t==='Messages from FTR'?'<button class="button" id="compose-ftr">New message +</button>':'')+'</div>'+(t==='Community moderation'?notice('Text-only member posts publish after language screening. Review member pictures and private prayer requests here. Public text-only prayer requests also publish after language screening. Private prayer requests cannot be published.')+'<div class="filters">'+['pending','published','rejected','reviewed'].map(x=>'<button class="filter '+(moderationStatus===x?'active':'')+'" data-modstatus="'+x+'">'+x+'</button>').join('')+'</div>':'')+(d.posts.length?d.posts.map(p=>'<article class="moderation-card"><div class="post-meta"><span>'+E(p.type)+' · '+E(p.status)+'</span><span class="pill">'+E(p.visibility)+'</span></div><h3>'+E(p.title)+'</h3><p class="post-author">'+E(p.author)+(p.email?' · '+E(p.email):'')+'</p><p class="post-body">'+E(p.body)+'</p>'+mediaMarkup(p)+'<div class="actions">'+(p.type==='message'?'<button class="filter" data-editmessage="'+E(p.id)+'">Edit</button>':p.visibility==='private'?'<button class="filter" data-moderate="resolve" data-id="'+E(p.id)+'">Mark reviewed</button>':'<button class="filter" data-moderate="approve" data-id="'+E(p.id)+'">Approve & publish</button>')+(p.status==='published'?'<button class="filter" data-moderate="unpublish" data-id="'+E(p.id)+'">Unpublish</button>':'')+(p.type!=='message'?'<button class="filter" data-moderate="reject" data-id="'+E(p.id)+'">Reject</button>':'')+'<button class="filter" data-moderate="delete" data-id="'+E(p.id)+'">Delete</button></div></article>').join(''):'<div class="empty">No '+(t==='Messages from FTR'?'messages':moderationStatus+' submissions')+' yet.</div>');}
function messageComposer(id){voiceRecordingFile=null;const p=adminPosts.find(p=>p.id===id)||{};modal('<h2 class="modal-title">'+(id?'Edit':'New')+' message from FTR</h2><form id="ftrmessageform" class="form" data-id="'+E(id||'')+'"><label>Title<input name="title" required maxlength="160" value="'+E(p.title)+'"></label><label>Message<textarea name="body" maxlength="10000">'+E(p.body)+'</textarea></label><label>Picture URL<input name="image" value="'+E(p.image)+'"></label><label>Or upload a picture<input name="imagefile" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Video URL (direct MP4, YouTube, or Vimeo)<input name="video" value="'+E(p.video)+'"></label><label>Or upload a video<input name="videofile" type="file" accept="video/mp4,video/webm"></label><label>Voice / audio URL (MP3, M4A, WAV, Ogg, WebM)<input name="audio" value="'+E(p.audio)+'"></label><label>Or upload a voice message<input name="audiofile" type="file" accept="audio/*"></label><div class="voice-tools"><button type="button" class="filter" id="recordvoice">Record a voice message</button><span id="voicestatus" role="status"></span><audio id="recordedvoice" controls hidden></audio></div><label>Shared link<input name="link" value="'+E(p.link)+'" placeholder="https://…"></label><label class="checklabel"><input type="checkbox" name="publish" '+(p.status==='published'?'checked':'')+'> Publish now (leave unchecked to save a draft)</label><button class="button">Save message ↗</button></form>');}
async function recordVoice(){const button=$('#recordvoice');if(voiceRecorder?.state==='recording'){voiceRecorder.stop();return;}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Voice recording is unavailable in this browser. Upload an audio file instead.');const generation=voiceGeneration;voiceStream=await navigator.mediaDevices.getUserMedia({audio:true});const activeStream=voiceStream;const mime=['audio/webm;codecs=opus','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x));voiceRecorder=new MediaRecorder(voiceStream,mime?{mimeType:mime}:{});const chunks=[];voiceRecorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};voiceRecorder.onstop=()=>{activeStream.getTracks().forEach(t=>t.stop());if(generation!==voiceGeneration)return;voiceStream=null;const type=voiceRecorder.mimeType.split(';')[0]||'audio/webm';voiceRecordingFile=new File(chunks,type==='audio/mp4'?'voice-message.m4a':'voice-message.webm',{type});if($('#recordedvoice')){const audio=$('#recordedvoice');if(audio.dataset.blob)URL.revokeObjectURL(audio.dataset.blob);audio.src=URL.createObjectURL(voiceRecordingFile);audio.dataset.blob=audio.src;audio.hidden=false;$('#voicestatus').textContent='Recording ready to save.';button.textContent='Record again';}clearTimeout(window.recordTimer);};voiceRecorder.start();$('#voicestatus').textContent='Recording… maximum 5 minutes';button.textContent='Stop recording';window.recordTimer=setTimeout(()=>{if(voiceRecorder?.state==='recording')voiceRecorder.stop()},300000);}
function stopVoice(){voiceGeneration++;voiceRecordingFile=null;if(voiceRecorder?.state==='recording')voiceRecorder.stop();voiceStream?.getTracks().forEach(t=>t.stop());voiceStream=null;clearTimeout(window.recordTimer);const audio=$('#recordedvoice');if(audio?.dataset.blob)URL.revokeObjectURL(audio.dataset.blob);}
$('#dialog').addEventListener('close',stopVoice);
window.addEventListener('hashchange',stopVoice);
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-fellowship')){fellowshipTab=b.dataset.fellowship;location.hash='#/fellowship?tab='+fellowshipTab;}else if(b.id==='more-fellowship')await loadFellowship(true);else if(b.id==='write-testimony')communityForm('testimony');else if(b.id==='write-prayer')communityForm('prayer');else if(b.hasAttribute('data-accounttab')){accountTab=b.dataset.accounttab;render();}else if(b.id==='memberlogout'){await api('/api/members/logout','POST',{});member=null;accountTab='login';render();}else if(b.id==='verifyemail'){b.disabled=true;await api('/api/members/verify','POST',{token:b.dataset.token});accountTab='login';location.hash='#/account';toast('Email verified. You can now sign in.');}else if(b.id==='compose-ftr')messageComposer();else if(b.hasAttribute('data-editmessage'))messageComposer(b.dataset.editmessage);else if(b.hasAttribute('data-modstatus')){moderationStatus=b.dataset.modstatus;await loadCommunityAdmin(tab);}else if(b.hasAttribute('data-moderate')){const post=adminPosts.find(p=>p.id===b.dataset.id);modal('<h2 class="modal-title">'+E(b.dataset.moderate)+' submission</h2><p class="modal-copy">'+E(post?.title)+'</p><form id="moderateform" class="form" data-id="'+E(b.dataset.id)+'" data-action="'+E(b.dataset.moderate)+'"><label>Note to the member (optional)<input name="note" maxlength="500"></label><button class="button">Confirm '+E(b.dataset.moderate)+'</button></form>');}else if(b.hasAttribute('data-postimage'))modal('<img class="full-event-poster" src="'+E(b.dataset.postimage)+'" alt="'+E(b.dataset.title)+'"><h2 class="modal-title">'+E(b.dataset.title)+'</h2>');else if(b.id==='recordvoice')await recordVoice();}catch(err){if(b.id==='verifyemail')b.disabled=false;toast(err.message)}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['communityform','memberlogin','signupform','forgotform','resendform','resetform','profileform','ftrmessageform','moderateform'].includes(f.id))return;e.preventDefault();const b=f.querySelector('button:not([type=button])');if(b)b.disabled=true;try{const d=Object.fromEntries(new FormData(f));if(f.id==='communityform'){const photo=d.memberimage;delete d.memberimage;if(photo?.size)d.image=await uploadMemberPicture(photo);const out=await api('/api/fellowship/submit','POST',{...d,type:f.dataset.type,anonymous:d.anonymous==='on',share_public:d.share_public==='on',consent_public:d.consent_public==='on'});$('#dialog').close();toast(out.message);}else if(f.id==='memberlogin'){const out=await api('/api/members/login','POST',d);member=out.member;render();toast('Welcome to FTR.');}else if(f.id==='signupform'){const out=await api('/api/members/signup','POST',{...d,consent:d.consent==='on'});modal('<h2 class="modal-title">Your next step</h2><p class="modal-copy">'+E(out.message)+'</p>');accountTab='login';render();}else if(f.id==='forgotform'||f.id==='resendform'){const out=await api('/api/members/'+(f.id==='forgotform'?'forgot':'resend'),'POST',{email:d.email});toast(out.message);}else if(f.id==='resetform'){await api('/api/members/reset','POST',{token:f.dataset.token,password:d.password});member=null;accountTab='login';location.hash='#/account';toast('Password reset. Sign in with your new password.');}else if(f.id==='profileform'){const out=await api('/api/members/profile','PUT',d);member=out.member;render();toast('Profile saved.');}else if(f.id==='moderateform'){await api('/api/fellowship/admin/moderate','POST',{id:f.dataset.id,action:f.dataset.action,note:d.note});$('#dialog').close();await loadCommunityAdmin(tab);toast('Moderation saved.');}else if(f.id==='ftrmessageform'){if(voiceRecorder?.state==='recording')throw Error('Stop the recording before saving.');for(const kind of ['image','video','audio']){const file=d[kind+'file'];if(file?.size)d[kind]=await upload(file);delete d[kind+'file'];}if(voiceRecordingFile)d.audio=await upload(voiceRecordingFile);await api('/api/fellowship/admin/message','POST',{...d,id:f.dataset.id||undefined,publish:d.publish==='on'});voiceRecordingFile=null;$('#dialog').close();await loadCommunityAdmin(tab);toast(d.publish==='on'?'Message published.':'Draft saved.');}}catch(err){toast(err.message)}finally{if(b)b.disabled=false}});

async function uploadMemberPicture(file){if(file.size>10*1024*1024)throw Error('Use a picture smaller than 10 MB.');const r=await fetch('/api/fellowship/upload-image',{method:'POST',headers:{'Content-Type':file.type},body:file});const d=await r.json();if(!r.ok)throw Error(d.error||'Picture upload failed.');return d.url;}
